import React, { useState, useMemo } from 'react';

export default function ExpensiveComponent() {
  const [count, setCount] = useState(0);
  const [text, setText] = useState('');

  // useMemo: Only recalculates when 'count' changes.
  // Typing in the text input will NOT trigger this expensive loop!
  const expensiveResult = useMemo(() => {
    console.log("Running expensive calculation...");
    let sum = 0;
    // Simulating a very heavy computation
    for (let i = 0; i < 100000000; i++) {
      sum += count;
    }
    return sum;
  }, [count]);

  return (
    <div>
      <h2>Count: {count}</h2>
      <h2>Expensive Math Result: {expensiveResult}</h2>

      <button onClick={() => setCount(c => c + 1)}>Increment Count</button>

      <br /><br />
      {/* Typing here causes re-renders, but useMemo protects the math! */}
      <input 
        type="text" 
        value={text} 
        onChange={(e) => setText(e.target.value)} 
        placeholder="Type here..."
      />
    </div>
  );
}
